/// Makes the feed's even rows show revision `revision` the next time they are fetched.
/// - Note: A failure is logged and passed to `LoadOptions.onError`; the method does not throw.
public func touchFeed(revision: UInt32, ctx: UndraCore = UndraPlaygroundCore.core) {
    var w = UndraWriter()
    revision.undraEncode(&w)
    do {
        _ = try ctx.callSync(
            .freeFunction(methodId: UndraIds.Functions.touchFeed),
            method: UndraIds.Functions.touchFeed,
            args: w.finish()
        )
    } catch {
        ctx.report(error, operation: "touchFeed")
    }
}

