/// Connects to `url`, sends `messages` in order, reads as many back and closes (1000).
///
/// Against an echo server the replies are the messages; any end of the connection before that is
/// the error (a refusal, `Closed` with the server's code, `Network`).
/// - Throws: ``WsError``, `CancellationError` if the task is cancelled, or ``UndraCallError``.
public func wsEcho(
    url: String,
    messages: [WsMessage],
    ctx: UndraCore = UndraPlaygroundCore.core
) async throws -> [WsMessage] {
    var w = UndraWriter()
    url.undraEncode(&w)
    messages.undraEncode(&w)
    do {
        let body = try await ctx.call(
            .freeFunction(methodId: UndraIds.Functions.wsEcho),
            method: UndraIds.Functions.wsEcho,
            args: w.finish()
        )
        return try [WsMessage].undraDecoded(from: body)
    } catch {
        throw UndraCallError.mapped(error, domain: WsError.self)
    }
}
